import com.vanniktech.maven.publish.JavaLibrary
import com.vanniktech.maven.publish.JavadocJar
import com.vanniktech.maven.publish.SourcesJar

/*
 * This file was generated by the Gradle 'init' task.
 *
 * This generated file contains a sample Java library project to get you started.
 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/current/userguide/building_java_projects.html in the Gradle documentation.
 */

group = "com.lemmingapex"
version = "1.1.0"

plugins {
    // Apply the java-library plugin for API and implementation separation.
    `java-library`
    // Publish the library to Maven Central: https://vanniktech.github.io/gradle-maven-publish-plugin/
    alias(libs.plugins.maven.publish)
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit test framework.
    testImplementation(libs.junit)
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion.set(JavaLanguageVersion.of(17))
    }
}

// Optionally run the tests on a different JDK than the one used to compile, e.g. ./gradlew test -PtestJavaVersion=25
val testJavaVersion = providers.gradleProperty("testJavaVersion").map(String::toInt)

tasks.test {
    testJavaVersion.orNull?.let { version ->
        javaLauncher = javaToolchains.launcherFor {
            languageVersion = JavaLanguageVersion.of(version)
        }
    }
    testLogging {
        events("PASSED", "SKIPPED", "FAILED")
    }
}

mavenPublishing {
    // publish the jar, a javadoc jar and a sources jar, like the 1.0.0 release
    configure(JavaLibrary(javadocJar = JavadocJar.Javadoc(), sourcesJar = SourcesJar.Sources()))

    // upload to the Sonatype Central Portal (https://central.sonatype.com). see RELEASING.md
    publishToMavenCentral()
    signAllPublications()

    coordinates(group.toString(), "rosemary", version.toString())

    pom {
        name = "Rosemary"
        description = "a robust and pattern-free datetime parser for java"
        inceptionYear = "2024"
        url = "https://github.com/lemmingapex/rosemary"
        licenses {
            license {
                name = "MIT License"
                url = "https://opensource.org/license/MIT"
                distribution = "repo"
            }
        }
        developers {
            developer {
                id = "lemmingapex"
                name = "Scott Wiedemann"
                email = "lemmingapex@gmail.com"
                url = "https://github.com/lemmingapex"
            }
        }
        scm {
            url = "https://github.com/lemmingapex/rosemary"
            connection = "scm:git:https://github.com/lemmingapex/rosemary.git"
            developerConnection = "scm:git:ssh://git@github.com/lemmingapex/rosemary.git"
        }
    }
}
